internal sealed class CpuSampler
{
    private ulong _prevIdle, _prevKernel, _prevUser;
    public double Sample()
    {
        if (!GetSystemTimes(out var idle, out var kernel, out var user)) return 0;
        ulong i = ToUInt64(idle), k = ToUInt64(kernel), u = ToUInt64(user);
        if (_prevKernel == 0) { store; return 0; }
        double idleDelta = i - _prevIdle;
        double total = (k - _prevKernel) + (u - _prevUser);
        ...
        return total <= 0 ? 0 : Math.Clamp((total - idleDelta) / total * 100, 0, 100);
    }
}
