```csharp
public sealed class CpuTemperatures : IDisposable
{
    private Computer? _computer;
    private IHardware? _cpu;
    private readonly object _gate = new();
    private int _initState; // 0 = not started, 1 = running, 2 = ready, 3 = failed
    public string Status { get; private set; } = "Initializing…";
    public bool Available { get; private set; }

    public void InitializeAsync() { if (Interlocked.Exchange(ref _initState,1)!=0) return; Task.Run(Init); }

    private void Init()
    {
        try {
            _computer = new Computer { IsCpuEnabled = true };
            _computer.Open();
            _cpu = _computer.Hardware.FirstOrDefault(h => h.HardwareType == HardwareType.Cpu);
            if (_cpu == null) throw new Exception("No CPU hardware found");
            _cpu.Update();
            var any = _cpu.Sensors.Any(s => s.SensorType == SensorType.Temperature && s.Value.HasValue);
            Available = any;
            Status = any ? "Available" : "No temperature sensors (run as administrator)";
            if (!any) { _computer.Close(); _computer = null; }
        } catch (Exception ex) {
            Status = "Unavailable — " + ex.Message;
            Available = false;
        }
    }

    public double Sample()
    {
        lock (_gate) {
            if (_computer == null || _cpu == null) return double.NaN;
            try {
                _cpu.Update();
                // Prefer specific sensors
                double? v = null;
                foreach (var s in _cpu.Sensors) {
                    if (s.SensorType != SensorType.Temperature || !s.Value.HasValue) continue;
                    var n = s.Name;
                    if (n.Contains("Package", StringComparison.OrdinalIgnoreCase) || n.Contains("Tctl", StringComparison.OrdinalIgnoreCase) || n.Contains("Core Max", StringComparison.OrdinalIgnoreCase))
                        return s.Value.Value;
                    v = Math.Max(v ?? double.MinValue, s.Value.Value);
                }
                return v ?? double.NaN;
            } catch { return double.NaN; }
        }
    }
    public double SamplePower() { ... SensorType.Power, prefer "Package" ... }
}
```
