public sealed class MetricsService : IDisposable
{
    private readonly CpuSampler _cpu = new();
    private readonly NetworkSampler _net = new();
    private readonly DiskSampler _disk = new();
    private readonly NvidiaGpu _gpu = new();
    public CpuTemperatures CpuTemps { get; } = new();
    private readonly object _gate = new();
    private Timer? _timer;
    private int _busy;
    private volatile bool _paused;

    public bool Paused { get => _paused; set => _paused = value; }
    public MetricsSnapshot Latest { get; private set; } = new();
    public event Action<MetricsSnapshot>? Updated;
    public string GpuStatus => _gpu.Status;

    public void Start(int intervalMs)
    {
        _gpu.Initialize();
        CpuTemps.InitializeAsync();
        _timer = new Timer(Tick, null, 0, Math.Clamp(intervalMs, 250, 10000));
    }

    public void SetInterval(int ms) => _timer?.Change(TimeSpan.Zero, TimeSpan.FromMilliseconds(Math.Clamp(ms, 250, 10000)));

    private void Tick(object? state)
    {
        if (_paused || Interlocked.Exchange(ref _busy, 1) == 1) return;
        try
        {
            var snap = new MetricsSnapshot();
            snap.CpuPercent = _cpu.Sample();
            snap.CpuTempC = CpuTemps.SampleTemperature();
            snap.CpuPowerW = CpuTemps.SamplePackagePower();
            MemoryInfo mem = MemorySampler.Sample();
            ...
            _gpu.Sample(ref snap);
            Latest = snap;
            Updated?.Invoke(snap);
        }
        catch (Exception ex) { Log.Error("metrics", ex); }
        finally { Interlocked.Exchange(ref _busy, 0); }
    }
}
