public sealed class MeterView : UserControl
{
    private readonly Border _panel;
    private readonly StackPanel _row1 = new() { Orientation = Horizontal };
    private readonly StackPanel _row2 = new() { Orientation = Horizontal };
    private readonly Dictionary<MetricKind, MetricView> _views = new();
    private AppSettings _settings;
    private ThemePalette _palette;
    private MetricView? _lastInRow1, _lastInRow2; // to remove trailing margin

    public MeterView() { Content = _panel = new Border { Child = new StackPanel { Children = { _row1, _row2 } } }; }

    public void Apply(AppSettings settings, ThemePalette palette)
    {
        _settings = settings; _palette = palette;
        _panel.Background = palette.BackgroundBrush;
        _panel.CornerRadius = new CornerRadius(settings.CornerRadius);
        _panel.Padding = new Thickness(settings.PaddingH, settings.PaddingV, settings.PaddingH, settings.PaddingV);
        Rebuild();
    }

    public void Rebuild()
    {
        _row1.Children.Clear(); _row2.Children.Clear(); _views.Clear();
        var blocks = _settings.Blocks.Where(b => b.Enabled)
            .OrderBy(b => b.Row).ThenBy(b => b.Order).ToList();
        foreach (var b in blocks)
        {
            var v = new MetricView(b, _settings, _palette);
            _views[b.Kind] = v;
            (b.Row == 2 ? _row2 : _row1).Children.Add(v);
        }
        // hide empty row
        _row2.Visibility = _row2.Children.Count > 0 ? Visibility.Visible : Visibility.Collapsed;
    }

    public void Update(MetricsSnapshot s)
    {
        foreach (var (kind, view) in _views) view.Update(s, _settings, _palette);
    }
}
