using System.Text.Json;
using System.Text.Json.Serialization;

namespace TaskbarMonitor;

public enum MetricKind
{
    Cpu,
    Gpu,
    Ram,
    Vram,
    NetUp,
    NetDown,
    DiskActivity,
    DiskSpace,
    Battery
}

public sealed class BlockSettings
{
    public MetricKind Kind { get; set; }
    public bool Enabled { get; set; } = true;
    public int Row { get; set; } = 1;
    public int Order { get; set; }
    public string? Label { get; set; }
    public bool ShowLabel { get; set; } = true;
    public bool ShowIcon { get; set; } = true;
    public bool ShowPercent { get; set; } = true;
    public bool ShowTemperature { get; set; } = true;
    public bool ShowPower { get; set; }

    public BlockSettings Clone() => (BlockSettings)MemberwiseClone();

    public string EffectiveLabel() =>
        string.IsNullOrWhiteSpace(Label) ? Kind.DefaultLabel() : Label!;
}

public sealed class AppSettings
{
    public int Version { get; set; } = 1;
    public int RefreshMs { get; set; } = 1000;

    public string Theme { get; set; } = "Auto";          // Auto | Light | Dark
    public bool UseThemePalette { get; set; } = true;
    public string BackgroundColor { get; set; } = "#F2F2F2";
    public double BackgroundOpacity { get; set; } = 0.94;
    public string LabelColor { get; set; } = "#1F6FB5";
    public string ValueColor { get; set; } = "#1A1A1A";
    public string TempColor { get; set; } = "#666666";
    public string WarningColor { get; set; } = "#E07B00";
    public string CriticalColor { get; set; } = "#D32F2F";

    public string FontFamily { get; set; } = "Segoe UI";
    public double FontSize { get; set; } = 12;
    public double Spacing { get; set; } = 12;

    public double OffsetFromRight { get; set; } = 0;      // 0 = auto (left of tray)
    public double GapFromTray { get; set; } = 8;
    public double OffsetY { get; set; } = 0;
    public bool ShowOnAllMonitors { get; set; }
    public string MonitorDevice { get; set; } = "";

    public bool StartWithWindows { get; set; }
    public bool StartElevated { get; set; }
    public string NetUnit { get; set; } = "Mbps";         // Mbps | MB/s

    public List<BlockSettings> Blocks { get; set; } = DefaultBlocks();

    public static List<BlockSettings> DefaultBlocks() => new()
    {
        new() { Kind = MetricKind.NetUp,   Row = 1, Order = 0, ShowLabel = false },
        new() { Kind = MetricKind.Cpu,     Row = 1, Order = 1 },
        new() { Kind = MetricKind.Ram,     Row = 1, Order = 2, ShowPercent = false, ShowTemperature = false },
        new() { Kind = MetricKind.NetDown, Row = 2, Order = 0, ShowLabel = false },
        new() { Kind = MetricKind.Gpu,     Row = 2, Order = 1 },
        new() { Kind = MetricKind.Vram,    Row = 2, Order = 2, ShowPercent = false, ShowTemperature = false },
        new() { Kind = MetricKind.DiskActivity, Row = 2, Order = 3, Enabled = false },
        new() { Kind = MetricKind.DiskSpace,    Row = 2, Order = 4, Enabled = false, ShowPercent = false, ShowTemperature = false },
        new() { Kind = MetricKind.Battery,      Row = 2, Order = 5, Enabled = false, ShowTemperature = false }
    };

    public AppSettings Clone()
    {
        var copy = (AppSettings)MemberwiseClone();
        copy.Blocks = Blocks.Select(b => b.Clone()).ToList();
        return copy;
    }

    public void Normalize()
    {
        Blocks ??= DefaultBlocks();
        foreach (var kind in Enum.GetValues<MetricKind>())
            if (Blocks.All(b => b.Kind != kind))
                Blocks.Add(new BlockSettings { Kind = kind, Enabled = false });

        Blocks.RemoveAll(b => !Enum.IsDefined(b.Kind));
        int row1 = 0, row2 = 0;
        foreach (var b in Blocks.Where(b => b.Row == 1).OrderBy(b => b.Order).ToList()) b.Order = row1++;
        foreach (var b in Blocks.Where(b => b.Row != 1).OrderBy(b => b.Order).ToList()) b.Row = 2;
        foreach (var b in Blocks.Where(b => b.Row == 2).OrderBy(b => b.Order).ToList()) b.Order = row2++;

        if (!Blocks.Any(b => b.Enabled)) Blocks[0].Enabled = true;

        RefreshMs = Math.Clamp(RefreshMs, 250, 10000);
        FontSize = Math.Clamp(FontSize, 8, 24);
        Spacing = Math.Clamp(Spacing, 0, 40);
        GapFromTray = Math.Clamp(GapFromTray, 0, 400);
        OffsetFromRight = Math.Clamp(OffsetFromRight, 0, 2000);
        OffsetY = Math.Clamp(OffsetY, -40, 60);
        BackgroundOpacity = Math.Clamp(BackgroundOpacity, 0.1, 1);
        if (string.IsNullOrWhiteSpace(FontFamily)) FontFamily = "Segoe UI";
        if (NetUnit != "MB/s") NetUnit = "Mbps";
        if (Theme is not ("Auto" or "Light" or "Dark")) Theme = "Auto";
    }
}

