private void Reposition()
{
    if (_hwnd == IntPtr.Zero) return;
    var tb = TaskbarLocator.GetAll()
        .Where(t => string.Equals(t.MonitorDevice, _monitor, StringComparison.OrdinalIgnoreCase))
        .OrderByDescending(t => t.IsPrimary ? 1 : 0)
        .FirstOrDefault();
    if (tb is null || tb.IsHidden) { SetVisible(false); return; }

    UpdateLayout();
    if (ActualWidth < 1 || ActualHeight < 1) return;

    var scale = Native.GetDpiForWindow(_hwnd) / 96.0;
    var w = (int)Math.Ceiling(ActualWidth * scale);
    var h = (int)Math.Ceiling(ActualHeight * scale);
    var gap = (int)Math.Round(App.Settings.GapFromTray * scale);

    int right = App.Settings.OffsetFromRight > 0
        ? tb.Rect.Right - (int)Math.Round(App.Settings.OffsetFromRight * scale)
        : (tb.HasTray ? tb.TrayRect.Left : tb.Rect.Right - (int)Math.Round(280 * scale)) - gap;

    int x = Math.Max(tb.Rect.Left, right - w);
    int y = tb.Rect.Top + (tb.Rect.Height - h) / 2 + (int)Math.Round(App.Settings.OffsetY * scale);

    Native.SetWindowPos(_hwnd, Native.HWND_TOPMOST, x, y, 0, 0, Native.SWP_NOSIZE | Native.SWP_NOACTIVATE | Native.SWP_SHOWWINDOW);
    SetVisible(true);
    if (Opacity < 1) Opacity = 1;
}
