        _mutex = new Mutex(true, @"Local\TaskbarMonitor.Instance", out firstInstance);
        if (!firstInstance)
        {
            if (e.Args.Contains("--replace", StringComparer.OrdinalIgnoreCase))
            {
                Signal("Local\\TaskbarMonitor.Exit");
                if (!_mutex.WaitOne(5000)) { MessageBox.Show("Another instance did not close."); Shutdown(); return; }
            }
            else
            {
