        AppDomain.CurrentDomain.UnhandledException += (_, args) => Log.Error("appdomain", args.ExceptionObject as Exception ?? new Exception("unknown"));

        Metrics.Updated += snapshot => Dispatcher.BeginInvoke(new Action(() =>
        {
            foreach (var overlay in Overlays) overlay.UpdateValues(snapshot);
            _settingsWindow?.UpdatePreview(snapshot);
        }));

        Metrics.Start(Settings.RefreshMs);
        RebuildOverlays();

        _showEvent = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\TaskbarMonitor.ShowSettings");
        _exitEvent = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\TaskbarMonitor.Exit");
        new Thread(Listen) { IsBackground = true }.Start();

        _saveTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(400) };
        _saveTimer.Tick += (_, _) => { _saveTimer!.Stop(); SettingsStore.Save(Settings); };

        _themeTimer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
        _themeTimer.Tick += (_, _) => { if (Settings.Theme == "Auto") ApplySettings(rebuild: false); };
        _themeTimer.Start();

