using System.Windows.Media;
using Microsoft.Win32;

namespace TaskbarMonitor;

public sealed class Palette
{
    public bool Light { get; init; }
    public SolidColorBrush Background { get; init; } = Brushes.Transparent;
    public SolidColorBrush Label { get; init; } = Brushes.Gray;
    public SolidColorBrush Value { get; init; } = Brushes.Black;
    public SolidColorBrush Temp { get; init; } = Brushes.Gray;
    public SolidColorBrush Warning { get; init; } = Brushes.Orange;
    public SolidColorBrush Critical { get; init; } = Brushes.Red;

    public static Palette Create(AppSettings settings)
    {
        var light = settings.Theme switch
        {
            "Light" => true,
            "Dark" => false,
            _ => SystemUsesLightTheme()
        };

        Color background, label, value, temp, warning, critical;
        if (settings.UseThemePalette)
        {
            if (light)
            {
                background = Color.FromRgb(0xF2, 0xF2, 0xF2);
                label = Color.FromRgb(0x1F, 0x6F, 0xB5);
                value = Color.FromRgb(0x1A, 0x1A, 0x1A);
                temp = Color.FromRgb(0x66, 0x66, 0x66);
                warning = Color.FromRgb(0xD9, 0x6C, 0x00);
                critical = Color.FromRgb(0xC6, 0x28, 0x28);
            }
            else
            {
                background = Color.FromRgb(0x1E, 0x1E, 0x1E);
                label = Color.FromRgb(0x6C, 0xB6, 0xFF);
                value = Color.FromRgb(0xF0, 0xF0, 0xF0);
                temp = Color.FromRgb(0xA8, 0xA8, 0xA8);
                warning = Color.FromRgb(0xFF, 0xB7, 0x4D);
                critical = Color.FromRgb(0xFF, 0x6B, 0x6B);
            }
        }
        else
        {
            background = Parse(settings.BackgroundColor, light ? Color.FromRgb(0xF2, 0xF2, 0xF2) : Color.FromRgb(0x1E, 0x1E, 0x1E));
            label = Parse(settings.LabelColor, Colors.SteelBlue);
            value = Parse(settings.ValueColor, light ? Colors.Black : Colors.White);
            temp = Parse(settings.TempColor, Colors.Gray);
            warning = Parse(settings.WarningColor, Colors.Orange);
            critical = Parse(settings.CriticalColor, Colors.Red);
        }

        var alpha = (byte)Math.Round(Math.Clamp(settings.BackgroundOpacity, 0.1, 1) * 255);
        background = Color.FromArgb(alpha, background.R, background.G, background.B);

        return new Palette
        {
            Light = light,
            Background = Freeze(new SolidColorBrush(background)),
            Label = Freeze(new SolidColorBrush(label)),
            Value = Freeze(new SolidColorBrush(value)),
            Temp = Freeze(new SolidColorBrush(temp)),
            Warning = Freeze(new SolidColorBrush(warning)),
            Critical = Freeze(new SolidColorBrush(critical))
        };
    }

    public static bool SystemUsesLightTheme()
    {
        try
        {
            using var key = Registry.CurrentUser.OpenSubKey(
                @"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize");
            return key?.GetValue("SystemUsesLightTheme") is not int value || value != 0;
        }
        catch
        {
            return true;
        }
    }

    public static Color Parse(string? hex, Color fallback)
    {
        try
        {
            return string.IsNullOrWhiteSpace(hex)
                ? fallback
                : (Color)ColorConverter.ConvertFromString(hex);
        }
        catch
        {
            return fallback;
        }
    }

    public static string ToHex(Color color) => $"#{color.R:X2}{color.G:X2}{color.B:X2}";

    private static SolidColorBrush Freeze(SolidColorBrush brush)
    {
        brush.Freeze();
        return brush;
    }
}

