/// <summary>One reading group: icon, label, main value and an extra suffix such as temperature.</summary>
internal sealed class MetricView : StackPanel
{
    private readonly BlockSettings _block;
    private readonly TextBlock _label = new();
    private readonly TextBlock _value = new();
    private readonly TextBlock _extra = new();

    public MetricView(BlockSettings block, AppSettings settings, Palette palette)
    {
        _block = block;
        Orientation = Orientation.Horizontal;
        VerticalAlignment = VerticalAlignment.Center;
        Margin = new Thickness(0, 0, settings.Spacing, 0);

        if (block.ShowIcon)
        {
            var path = new Path
            {
                Data = Icons.Get(block.Kind),
                Fill = new SolidColorBrush(IconColor(block.Kind, palette.Light)),
                Width = 13,
                Height = 13,
                Stretch = Stretch.Uniform,
                VerticalAlignment = VerticalAlignment.Center
            };
            Children.Add(path);
        }

        foreach (var text in new[] { _label, _value, _extra })
        {
            text.FontFamily = new FontFamily(settings.FontFamily);
            text.FontSize = settings.FontSize;
            text.VerticalAlignment = VerticalAlignment.Center;
            text.SnapsToDevicePixels = true;
        }

        _label.Margin = new Thickness(4, 0, 0, 0);
        _value.Margin = new Thickness(4, 0, 0, 0);
        _extra.Margin = new Thickness(3, 0, 0, 0);

        Children.Add(_label);
        Children.Add(_value);
        Children.Add(_extra);
    }

    public void Update(MetricsSnapshot snapshot, AppSettings settings, Palette palette)
    {
        var (label, value, extras, percent) = Format(snapshot, settings);
        var alert = AlertBrush(percent, palette);

        _label.Text = _block.ShowLabel ? _block.EffectiveLabel() : "";
        _label.Visibility = _label.Text.Length > 0 ? Visibility.Visible : Visibility.Collapsed;
        _label.Foreground = palette.Label;

        var temperatureAlert = extras.Any(e => e.IsHot && e.IsHotHot) ? palette.Critical
            : extras.Any(e => e.IsHot) ? palette.Warning
            : null;
        var hot = temperatureAlert ?? alert;

        _value.Text = value;
        _value.Foreground = hot ?? palette.Value;

        var extraText = extras.Count == 0 ? "" : "(" + string.Join(" ", extras.Select(e => e.Text)) + ")";
        _extra.Text = extraText;
        _extra.Visibility = extraText.Length > 0 ? Visibility.Visible : Visibility.Collapsed;
        _extra.Foreground = temperatureAlert ?? palette.Temp;
    }

    private readonly record struct Extra(string Text, bool IsHot, bool IsHotHot = false);

    private (string label, string value, List<Extra> extras, double percent) Format(
        MetricsSnapshot s, AppSettings settings)
    {
        var extras = new List<Extra>();
        double percent = double.NaN;
        string value;

        void AddTemperature(double celsius)
        {
            if (!_block.ShowTemperature || double.IsNaN(celsius)) return;
            extras.Add(new Extra($"{celsius:0}°C", celsius >= 85, celsius >= 95));
        }

        void AddPower(double watts)
        {
            if (!_block.ShowPower || double.IsNaN(watts)) return;
            extras.Add(new Extra($"{watts:0}W", false));
        }

        void AddPercent(double p)
        {
            if (!_block.ShowPercent || double.IsNaN(p)) return;
            extras.Add(new Extra($"{p:0}%", false));
        }

        switch (_block.Kind)
        {
            case MetricKind.Cpu:
                percent = s.CpuPercent;
                value = $"{s.CpuPercent:0}%";
                AddTemperature(s.CpuTemp);
                AddPower(s.CpuPowerW);
                break;

            case MetricKind.Gpu:
                percent = s.GpuPercent;
                value = double.IsNaN(s.GpuPercent) ? "--" : $"{s.GpuPercent:0}%";
                AddTemperature(s.GpuTemp);
                AddPower(s.GpuPowerW);
                break;

            case MetricKind.Ram:
                percent = s.RamTotal > 0 ? s.RamUsed * 100.0 / s.RamTotal : double.NaN;
                value = $"{Gib(s.RamUsed):0.0}/{Gib(s.RamTotal):0.0}G";
                AddPercent(percent);
                break;

            case MetricKind.Vram:
                percent = s.VramTotal > 0 ? s.VramUsed * 100.0 / s.VramTotal : double.NaN;
                value = s.VramTotal > 0 ? $"{Gib(s.VramUsed):0.0}/{Gib(s.VramTotal):0.0}G" : "--";
                AddTemperature(s.GpuTemp);
                AddPercent(percent);
                break;

            case MetricKind.NetUp:
                value = FormatRate(s.NetUp, settings.NetUnit);
                break;

            case MetricKind.NetDown:
                value = FormatRate(s.NetDown, settings.NetUnit);
                break;

            case MetricKind.DiskActivity:
                percent = s.DiskActivity;
                value = double.IsNaN(s.DiskActivity) ? "--" : $"{s.DiskActivity:0}%";
                break;

            case MetricKind.DiskSpace:
                percent = s.DiskTotal > 0 ? s.DiskUsed * 100.0 / s.DiskTotal : double.NaN;
                value = $"{Gib(s.DiskUsed):0.0}/{Gib(s.DiskTotal):0.0}G";
                AddPercent(percent);
                break;

            case MetricKind.Battery:
                percent = s.BatteryPercent;
                value = s.HasBattery ? $"{s.BatteryPercent}%" : "--";
                if (s.HasBattery) extras.Add(new Extra(s.OnAc ? "AC" : "BAT", false));
                break;

            default:
                value = "--";
                break;
        }

        return (_block.EffectiveLabel(), value, extras, percent);
    }

    private SolidColorBrush? AlertBrush(double percent, Palette palette)
    {
        if (double.IsNaN(percent)) return null;
        if (percent >= 92) return palette.Critical;
        if (percent >= 80) return palette.Warning;
        return null;
    }

    private static double Gib(long bytes) => bytes / 1024.0 / 1024.0 / 1024.0;

    private static string FormatRate(double bytesPerSecond, string unit)
    {
        if (!double.IsFinite(bytesPerSecond) || bytesPerSecond < 0) bytesPerSecond = 0;
        return unit == "MB/s"
            ? $"{bytesPerSecond / 1_000_000.0:0.0} MB/s"
            : $"{bytesPerSecond * 8 / 1_000_000.0:0.0} Mbps";
    }

    private static Color IconColor(MetricKind kind, bool light) => kind switch
    {
        MetricKind.Cpu => Color.FromRgb(0x2D, 0x7F, 0xF9),
        MetricKind.Gpu => Color.FromRgb(0x43, 0xA0, 0x47),
        MetricKind.Ram => Color.FromRgb(0x7E, 0x57, 0xC2),
        MetricKind.Vram => Color.FromRgb(0x26, 0xA6, 0x9A),
        MetricKind.NetUp => Color.FromRgb(0x00, 0xA3, 0xE0),
        MetricKind.NetDown => Color.FromRgb(0x1E, 0x88, 0xE5),
        MetricKind.DiskActivity => Color.FromRgb(0xF5, 0x7C, 0x00),
        MetricKind.DiskSpace => Color.FromRgb(0xF5, 0x7C, 0x00),
        MetricKind.Battery => Color.FromRgb(0x66, 0xBB, 0x6A),
        _ => Colors.Gray
    };
}

public sealed class MeterView : UserControl
{
    private readonly Border _panel = new();
    private readonly StackPanel _row1 = new() { Orientation = Orientation.Horizontal };
    private readonly StackPanel _row2 = new() { Orientation = Orientation.Horizontal };
    private readonly List<MetricView> _views = new();
    private AppSettings _settings = new();
    private Palette _palette = Palette.Create(new AppSettings());

    public MeterView()
    {
        _panel.Child = new StackPanel { Children = { _row1, _row2 } };
        _panel.SnapsToDevicePixels = true;
        Content = _panel;
        HorizontalAlignment = HorizontalAlignment.Left;
        VerticalAlignment = VerticalAlignment.Center;
    }

    public void Apply(AppSettings settings, Palette palette)
    {
        _settings = settings;
        _palette = palette;
        _panel.Background = palette.Background;
        _panel.CornerRadius = new CornerRadius(4);
        _panel.Padding = new Thickness(8, 2, 8, 2);
        Rebuild();
    }

    private void Rebuild()
    {
        _row1.Children.Clear();
        _row2.Children.Clear();
        _views.Clear();

        foreach (var block in _settings.Blocks.Where(b => b.Enabled).OrderBy(b => b.Row).ThenBy(b => b.Order))
        {
            var view = new MetricView(block, _settings, _palette);
            _views.Add(view);
            (block.Row == 2 ? _row2 : _row1).Children.Add(view);
        }

        TrimTrailingSpace(_row1);
        TrimTrailingSpace(_row2);
        _row2.Visibility = _row2.Children.Count > 0 ? Visibility.Visible : Visibility.Collapsed;

        if (_views.Count > 0) UpdateValues(App.Latest);
    }

    private static void TrimTrailingSpace(StackPanel row)
    {
        if (row.Children.Count == 0) return;
        if (row.Children[^1] is FrameworkElement last) last.Margin = new Thickness(0);
    }

    public void UpdateValues(MetricsSnapshot snapshot)
    {
        foreach (var view in _views) view.Update(snapshot, _settings, _palette);
    }

    public void ApplyStyle(AppSettings settings, Palette palette)
    {
        _settings = settings;
        _palette = palette;
        _panel.Background = palette.Background;
        foreach (var view in _views) view.Update(App.Latest, _settings, _palette);
    }
}

