using System.Windows;
using System.Windows.Controls;
using System.Windows.Interop;
using System.Windows.Media;
using System.Windows.Threading;
using WinForms = System.Windows.Forms;

namespace TaskbarMonitor;

public sealed class OverlayWindow : Window
{
    private readonly MeterView _view = new();
    private readonly string _monitorDevice;
    private readonly DispatcherTimer _positionTimer;
    private IntPtr _hwnd;
    private bool _shown = true;

    public OverlayWindow(string monitorDevice)
    {
        _monitorDevice = monitorDevice;

        WindowStyle = WindowStyle.None;
        AllowsTransparency = true;
        Background = Brushes.Transparent;
        ShowInTaskbar = false;
        ShowActivated = false;
        Topmost = true;
        ResizeMode = ResizeMode.NoResize;
        SizeToContent = SizeToContent.WidthAndHeight;
        WindowStartupLocation = WindowStartupLocation.Manual;
        Focusable = false;
        Opacity = 0;

        _view.Apply(App.Settings, App.CurrentPalette);
        Content = _view;
        ContextMenu = CreateMenu();

        SizeChanged += (_, _) => Position();
        Loaded += (_, _) => Dispatcher.BeginInvoke(new Action(() =>
        {
            Position();
            Opacity = 1;
        }), DispatcherPriority.Loaded);

        _positionTimer = new DispatcherTimer(TimeSpan.FromMilliseconds(300), DispatcherPriority.Background,
            (_, _) => Position(), Dispatcher);
        _positionTimer.Start();
    }

    protected override void OnSourceInitialized(EventArgs e)
    {
        base.OnSourceInitialized(e);
        _hwnd = new WindowInteropHelper(this).Handle;
        var style = Native.GetWindowLongPtr(_hwnd, Native.GWL_EXSTYLE).ToInt64();
        Native.SetWindowLongPtr(_hwnd, Native.GWL_EXSTYLE,
            new IntPtr(style | Native.WS_EX_TOOLWINDOW | Native.WS_EX_NOACTIVATE));
    }

    public void UpdateValues(MetricsSnapshot snapshot) => _view.UpdateValues(snapshot);

    public void Reload(bool rebuildBlocks)
    {
        if (rebuildBlocks) _view.Apply(App.Settings, App.CurrentPalette);
        else _view.ApplyStyle(App.Settings, App.CurrentPalette);
        Dispatcher.BeginInvoke(new Action(Position), DispatcherPriority.Loaded);
    }

    private void Position()
    {
        if (_hwnd == IntPtr.Zero) return;

        var taskbar = TaskbarLocator.GetAll()
            .Where(t => string.Equals(t.MonitorDevice, _monitorDevice, StringComparison.OrdinalIgnoreCase))
            .OrderByDescending(t => t.IsPrimary)
            .FirstOrDefault();

        if (taskbar is null || taskbar.IsHidden)
        {
            SetVisible(false);
            return;
        }

        UpdateLayout();
        if (ActualWidth < 1 || ActualHeight < 1) return;

        var scale = Native.GetDpiForWindow(_hwnd) / 96.0;
        var width = (int)Math.Ceiling(ActualWidth * scale);
        var height = (int)Math.Ceiling(ActualHeight * scale);
        var gap = (int)Math.Round(App.Settings.GapFromTray * scale);
        var verticalOffset = (int)Math.Round(App.Settings.OffsetY * scale);

        var verticalTaskbar = taskbar.Rect.Height > taskbar.Rect.Width;

        int x, y;
        if (verticalTaskbar)
        {
            // shortcut: vertical taskbars get a floating block beside them, not a rotated one
            x = taskbar.Rect.Height > 0 && taskbar.Rect.Left > 0
                ? taskbar.Rect.Left - width - gap
                : taskbar.Rect.Right + gap;
            y = taskbar.Rect.Bottom - height - gap;
        }
        else
        {
            var right = App.Settings.OffsetFromRight > 0
                ? taskbar.Rect.Right - (int)Math.Round(App.Settings.OffsetFromRight * scale)
                : (taskbar.HasTray ? taskbar.TrayRect.Left : taskbar.Rect.Right - (int)Math.Round(300 * scale)) - gap;

            x = Math.Max(taskbar.Rect.Left, right - width);
            y = taskbar.Rect.Top + (taskbar.Rect.Height - height) / 2 + verticalOffset;
        }

        Native.SetWindowPos(_hwnd, Native.HWND_TOPMOST, x, y, 0, 0,
            Native.SWP_NOSIZE | Native.SWP_NOACTIVATE | Native.SWP_SHOWWINDOW);
        SetVisible(true);
        if (Opacity < 1) Opacity = 1;
    }

    private void SetVisible(bool visible)
    {
        if (_hwnd == IntPtr.Zero || visible == _shown) return;
        _shown = visible;
        Native.ShowWindow(_hwnd, visible ? Native.SW_SHOWNOACTIVATE : Native.SW_HIDE);
    }

    private ContextMenu CreateMenu()
    {
        var menu = new ContextMenu();
        menu.Opened += (_, _) =>
        {
            menu.Items.Clear();

            var settings = new MenuItem { Header = "Settings…" };
            settings.Click += (_, _) => App.ShowSettings();
            menu.Items.Add(settings);

            var pause = new MenuItem
            {
                Header = "Pause readings",
                IsCheckable = true,
                IsChecked = App.Metrics.Paused
            };
            pause.Click += (_, _) => App.Metrics.Paused = pause.IsChecked;
            menu.Items.Add(pause);

            var startup = new MenuItem
            {
                Header = "Start with Windows",
                IsCheckable = true,
                IsChecked = App.Settings.StartWithWindows
            };
            startup.Click += (_, _) =>
            {
                App.Settings.StartWithWindows = startup.IsChecked;
                Startup.Apply(App.Settings.StartWithWindows, App.Settings.StartElevated);
                App.QueueSave();
            };
            menu.Items.Add(startup);

            menu.Items.Add(new Separator());

            var exit = new MenuItem { Header = "Exit" };
            exit.Click += (_, _) => App.ExitApp();
            menu.Items.Add(exit);
        };
        return menu;
    }

    protected override void OnClosed(EventArgs e)
    {
        _positionTimer.Stop();
        base.OnClosed(e);
    }
}

using System.Diagnostics;
using System.Security.Principal;
using System.Windows;
using System.Windows.Threading;

namespace TaskbarMonitor;

public partial class App : Application
{
    private const string MutexName = @"Local\TaskbarMonitor.Instance";
    private const string ShowEventName = @"Local\TaskbarMonitor.ShowSettings";
    private const string ExitEventName = @"Local\TaskbarMonitor.Exit";

    private static Mutex? _mutex;
    private static EventWaitHandle? _showEvent;
    private static EventWaitHandle? _exitEvent;
    private static DispatcherTimer? _saveTimer;
    private static DispatcherTimer? _themeTimer;
    private static bool? _lastSystemLight;
    private static bool _shuttingDown;

    public static AppSettings Settings { get; private set; } = new();
    public static Palette CurrentPalette { get; private set; } = Palette.Create(new AppSettings());
    public static MetricsService Metrics { get; } = new();
    public static List<OverlayWindow> Overlays { get; } = new();
    public static SettingsWindow? SettingsWindowInstance { get; private set; }
    public static bool IsElevated { get; private set; }
    public static MetricsSnapshot Latest => Metrics.Latest;

    protected override void OnStartup(StartupEventArgs e)
    {
        base.OnStartup(e);

        _mutex = new Mutex(true, MutexName, out var firstInstance);
        if (!firstInstance)
        {
            if (e.Args.Contains("--replace", StringComparer.OrdinalIgnoreCase))
            {
                Signal(ExitEventName);
                try
                {
                    if (!_mutex.WaitOne(TimeSpan.FromSeconds(6)))
                    {
                        MessageBox.Show("The previous instance did not close. Please try again.",
                            "Taskbar Monitor", MessageBoxButton.OK, MessageBoxImage.Warning);
                        Shutdown();
                        return;
                    }
                }
                catch (AbandonedMutexException)
                {
                    // previous instance crashed; we own the mutex now
                }
            }
            else
            {
                Signal(ShowEventName);
                Shutdown();
                return;
            }
        }

        IsElevated = CheckElevated();
        Settings = SettingsStore.Load();
        Settings.Normalize();
        CurrentPalette = Palette.Create(Settings);
        SettingsStore.Save(Settings);

        DispatcherUnhandledException += (_, args) =>
        {
            Log.Error("dispatcher", args.Exception);
            args.Handled = true;
        };
        AppDomain.CurrentDomain.UnhandledException += (_, args) =>
            Log.Error("appdomain", args.ExceptionObject as Exception ?? new Exception("unknown failure"));

        Metrics.Updated += snapshot => Dispatcher.BeginInvoke(new Action(() =>
        {
            foreach (var overlay in Overlays) overlay.UpdateValues(snapshot);
            SettingsWindowInstance?.UpdatePreview(false);
        }));

        _saveTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(400) };
        _saveTimer.Tick += (_, _) =>
        {
            _saveTimer!.Stop();
            SettingsStore.Save(Settings);
        };

        _themeTimer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
        _themeTimer.Tick += (_, _) => FollowSystemTheme();
        _themeTimer.Start();

        _showEvent = new EventWaitHandle(false, EventResetMode.AutoReset, ShowEventName);
        _exitEvent = new EventWaitHandle(false, EventResetMode.AutoReset, ExitEventName);
        new Thread(ListenForSignals) { IsBackground = true }.Start();

        Metrics.Start(Settings.RefreshMs);
        RebuildOverlays();

        if (!e.Args.Any(a => a.Equals("--silent", StringComparison.OrdinalIgnoreCase)))
            ShowSettings();
    }

    public static void ShowSettings()
    {
        if (SettingsWindowInstance is { IsVisible: true })
        {
            SettingsWindowInstance.Activate();
            return;
        }

        SettingsWindowInstance = new SettingsWindow();
        SettingsWindowInstance.Closed += (_, _) => SettingsWindowInstance = null;
        SettingsWindowInstance.Show();
    }

    public static void ApplySettings(bool rebuildBlocks = true)
    {
        Settings.Normalize();
        CurrentPalette = Palette.Create(Settings);
        Metrics.SetInterval(Settings.RefreshMs);

        foreach (var overlay in Overlays) overlay.Reload(rebuildBlocks);
        SettingsWindowInstance?.UpdatePreview(rebuildBlocks);
        QueueSave();
    }

    public static void RebuildOverlays()
    {
        foreach (var overlay in Overlays.ToList()) overlay.Close();
        Overlays.Clear();

        var taskbars = TaskbarLocator.GetAll();
        List<TaskbarInfo> targets;

        if (Settings.ShowOnAllMonitors)
        {
            targets = taskbars;
        }
        else
        {
            var chosen = taskbars.FirstOrDefault(t =>
                             string.Equals(t.MonitorDevice, Settings.MonitorDevice, StringComparison.OrdinalIgnoreCase))
                         ?? taskbars.FirstOrDefault(t => t.IsPrimary)
                         ?? taskbars.FirstOrDefault();

            targets = chosen is null ? new List<TaskbarInfo>() : new List<TaskbarInfo> { chosen };
        }

        if (targets.Count == 0)
        {
            // No taskbar window found: keep the primary monitor so the user still sees something.
            targets.Add(new TaskbarInfo { MonitorDevice = "" });
        }

        foreach (var target in targets)
        {
            var overlay = new OverlayWindow(target.MonitorDevice);
            overlay.Show();
            Overlays.Add(overlay);
        }
    }

    public static void QueueSave()
    {
        if (_saveTimer is null) return;
        _saveTimer.Stop();
        _saveTimer.Start();
    }

    public static void TogglePause() => Metrics.Paused = !Metrics.Paused;

    public static void RestartElevated()
    {
        try
        {
            SettingsStore.Save(Settings);
            var path = Environment.ProcessPath;
            if (path is null) return;
            Process.Start(new ProcessStartInfo(path, "--replace")
            {
                UseShellExecute = true,
                Verb = "runas"
            });
            ExitApp();
        }
        catch (Exception ex)
        {
            Log.Error("restart elevated", ex);
        }
    }

    public static void ExitApp()
    {
        if (_shuttingDown) return;
        _shuttingDown = true;

        SettingsStore.Save(Settings);
        Metrics.Dispose();

        foreach (var overlay in Overlays.ToList()) overlay.Close();
        Overlays.Clear();

        SettingsWindowInstance?.Close();
        SettingsWindowInstance = null;

        try { _mutex?.ReleaseMutex(); } catch { }
        _mutex?.Dispose();
        _mutex = null;

        Shutdown();
    }

    private static void FollowSystemTheme()
    {
        var light = Palette.SystemUsesLightTheme();
        if (_lastSystemLight == light) return;
        _lastSystemLight = light;

        if (Settings.Theme == "Auto" && Settings.UseThemePalette)
        {
            CurrentPalette = Palette.Create(Settings);
            foreach (var overlay in Overlays) overlay.Reload(rebuildBlocks: false);
            SettingsWindowInstance?.UpdatePreview(false);
        }
    }

    private static void ListenForSignals()
    {
        var handles = new WaitHandle[] { _showEvent!, _exitEvent! };
        while (!_shuttingDown)
        {
            int index;
            try { index = WaitHandle.WaitAny(handles); }
            catch { break; }

            if (index == 0) Dispatcher.BeginInvoke(new Action(ShowSettings));
            else
            {
                Dispatcher.BeginInvoke(new Action(ExitApp));
                break;
            }
        }
    }

    private static void Signal(string name)
    {
        try { EventWaitHandle.OpenExisting(name).Set(); }
        catch { /* no other instance listening */ }
    }

    private static bool CheckElevated()
    {
        try
        {
            using var identity = WindowsIdentity.GetCurrent();
            return new WindowsPrincipal(identity).IsInRole(WindowsBuiltInRole.Administrator);
        }
        catch
        {
            return false;
        }
    }
}

