using System.Diagnostics;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
using WinForms = System.Windows.Forms;

namespace TaskbarMonitor;

public partial class SettingsWindow : Window
{
    private readonly MeterView _preview = new();
    private readonly List<Action> _colorRefreshers = new();
    private readonly List<FrameworkElement> _colorEditors = new();
    private readonly DispatcherTimer _statusTimer;
    private BlockSettings? _selectedBlock;
    private bool _loading;

    private sealed record MonitorEntry(string Device, string Display);

    public SettingsWindow()
    {
        InitializeComponent();

        PreviewHost.Content = _preview;
        BuildChoices();
        BuildColorRows();
        LoadFromSettings();
        HookEvents();

        UpdatePreview(true);
        UpdateStatus();

        _statusTimer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
        _statusTimer.Tick += (_, _) => UpdateStatus();
        _statusTimer.Start();
        Closed += (_, _) => _statusTimer.Stop();
    }

    private void BuildChoices()
    {
        ThemeCombo.ItemsSource = new[] { "Auto", "Light", "Dark" };
        FontCombo.ItemsSource = new[] { "Segoe UI", "Segoe UI Variable Text", "Tahoma", "Consolas", "Bahnschrift", "Arial" };
        NetUnitCombo.ItemsSource = new[] { "Mbps", "MB/s" };
    }

    private void BuildColorRows()
    {
        AddColorRow("Panel background", () => App.Settings.BackgroundColor, v => App.Settings.BackgroundColor = v);
        AddColorRow("Label", () => App.Settings.LabelColor, v => App.Settings.LabelColor = v);
        AddColorRow("Value", () => App.Settings.ValueColor, v => App.Settings.ValueColor = v);
        AddColorRow("Temperature", () => App.Settings.TempColor, v => App.Settings.TempColor = v);
        AddColorRow("Warning", () => App.Settings.WarningColor, v => App.Settings.WarningColor = v);
        AddColorRow("Critical", () => App.Settings.CriticalColor, v => App.Settings.CriticalColor = v);
    }

    private void AddColorRow(string title, Func<string> get, Action<string> set)
    {
        var row = new Grid { Margin = new Thickness(0, 3, 0, 3) };
        row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(150) });
        row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
        row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        var label = new TextBlock { Text = title, VerticalAlignment = VerticalAlignment.Center };

        var swatch = new Button
        {
            Width = 46,
            Height = 22,
            Padding = new Thickness(0),
            Margin = new Thickness(0),
            MinWidth = 0,
            BorderThickness = new Thickness(1),
            BorderBrush = new SolidColorBrush(Color.FromRgb(0xD0, 0xD0, 0xD0))
        };

        var hex = new TextBlock
        {
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(10, 0, 0, 0),
            FontFamily = new FontFamily("Consolas"),
            FontSize = 12,
            Foreground = new SolidColorBrush(Color.FromRgb(0x66, 0x66, 0x66))
        };

        swatch.Click += (_, _) => PickColor(get, set);

        Grid.SetColumn(swatch, 1);
        Grid.SetColumn(hex, 2);
        row.Children.Add(label);
        row.Children.Add(swatch);
        row.Children.Add(hex);
        ColorsPanel.Children.Add(row);
        _colorEditors.Add(row);

        _colorRefreshers.Add(() =>
        {
            var color = Palette.Parse(get(), Colors.Gray);
            swatch.Background = new SolidColorBrush(color);
            hex.Text = get();
        });
    }

    private void PickColor(Func<string> get, Action<string> set)
    {
        using var dialog = new WinForms.ColorDialog { FullOpen = true, AnyColor = true };
        var current = Palette.Parse(get(), Colors.Gray);
        dialog.Color = System.Drawing.Color.FromArgb(current.R, current.G, current.B);

        if (dialog.ShowDialog() != WinForms.DialogResult.OK) return;

        set(Palette.ToHex(Color.FromRgb(dialog.Color.R, dialog.Color.G, dialog.Color.B)));
        if (App.Settings.UseThemePalette)
        {
            // Picking a color means the user wants custom colors.
            App.Settings.UseThemePalette = false;
            UsePaletteCheck.IsChecked = false;
        }
        UpdateColorAvailability();
        RefreshColors();
        Apply();
    }

    private void RefreshColors()
    {
        foreach (var refresh in _colorRefreshers) refresh();
    }

    private void UpdateColorAvailability()
    {
        var enabled = UsePaletteCheck.IsChecked != true;
        foreach (var editor in _colorEditors) editor.IsEnabled = enabled;
    }

    private void HookEvents()
    {
        ThemeCombo.SelectionChanged += (_, _) => Apply();
        UsePaletteCheck.Checked += (_, _) => { UpdateColorAvailability(); Apply(); };
        UsePaletteCheck.Unchecked += (_, _) => { UpdateColorAvailability(); Apply(); };
        FontCombo.SelectionChanged += (_, _) => Apply();

        SizeSlider.ValueChanged += (_, _) => { SizeValue.Text = $"{SizeSlider.Value:0}"; Apply(); };
        SpacingSlider.ValueChanged += (_, _) => { SpacingValue.Text = $"{SpacingSlider.Value:0}"; Apply(); };
        OpacitySlider.ValueChanged += (_, _) => { OpacityValue.Text = $"{OpacitySlider.Value * 100:0}%"; Apply(); };

        NetUnitCombo.SelectionChanged += (_, _) => Apply();

        AllMonitorsCheck.Checked += (_, _) => { MonitorCombo.IsEnabled = false; Apply(rebuildOverlays: true); };
        AllMonitorsCheck.Unchecked += (_, _) => { MonitorCombo.IsEnabled = true; Apply(rebuildOverlays: true); };
        MonitorCombo.SelectionChanged += (_, _) => Apply(rebuildOverlays: true);

        GapSlider.ValueChanged += (_, _) => { GapValue.Text = $"{GapSlider.Value:0}"; Apply(); };
        RightOffsetSlider.ValueChanged += (_, _) => { RightOffsetValue.Text = $"{RightOffsetSlider.Value:0}"; Apply(); };
        VerticalSlider.ValueChanged += (_, _) => { VerticalValue.Text = $"{VerticalSlider.Value:0}"; Apply(); };

        StartWithWindowsCheck.Checked += (_, _) => StartupChanged();
        StartWithWindowsCheck.Unchecked += (_, _) => StartupChanged();
        StartElevatedCheck.Checked += (_, _) => StartupChanged();
        StartElevatedCheck.Unchecked += (_, _) => StartupChanged();

        LabelBox.TextChanged += (_, _) =>
        {
            if (_loading || _selectedBlock is null) return;
            _selectedBlock.Label = string.IsNullOrWhiteSpace(LabelBox.Text) ? null : LabelBox.Text.Trim();
            Apply();
        };

        ChkIcon.Checked += (_, _) => DetailChanged();
        ChkIcon.Unchecked += (_, _) => DetailChanged();
        ChkLabel.Checked += (_, _) => DetailChanged();
        ChkLabel.Unchecked += (_, _) => DetailChanged();
        ChkPercent.Checked += (_, _) => DetailChanged();
        ChkPercent.Unchecked += (_, _) => DetailChanged();
        ChkTemp.Checked += (_, _) => DetailChanged();
        ChkTemp.Unchecked += (_, _) => DetailChanged();
        ChkPower.Checked += (_, _) => DetailChanged();
        ChkPower.Unchecked += (_, _) => DetailChanged();
    }

    private void DetailChanged()
    {
        if (_loading || _selectedBlock is null) return;
        _selectedBlock.ShowIcon = ChkIcon.IsChecked == true;
        _selectedBlock.ShowLabel = ChkLabel.IsChecked == true;
        _selectedBlock.ShowPercent = ChkPercent.IsChecked == true;
        _selectedBlock.ShowTemperature = ChkTemp.IsChecked == true;
        _selectedBlock.ShowPower = ChkPower.IsChecked == true;
        Apply();
    }

    private void LoadFromSettings()
    {
        _loading = true;

        var settings = App.Settings;
        var selectedKind = _selectedBlock?.Kind;

        ThemeCombo.SelectedItem = settings.Theme;
        UsePaletteCheck.IsChecked = settings.UseThemePalette;
        FontCombo.SelectedItem = settings.FontFamily;
        SizeSlider.Value = settings.FontSize;
        SpacingSlider.Value = settings.Spacing;
        OpacitySlider.Value = settings.BackgroundOpacity;
        NetUnitCombo.SelectedItem = settings.NetUnit;
        AllMonitorsCheck.IsChecked = settings.ShowOnAllMonitors;
        GapSlider.Value = settings.GapFromTray;
        RightOffsetSlider.Value = settings.OffsetFromRight;
        VerticalSlider.Value = settings.OffsetY;
        StartWithWindowsCheck.IsChecked = settings.StartWithWindows;
        StartElevatedCheck.IsChecked = settings.StartElevated;

        SizeValue.Text = $"{settings.FontSize:0}";
        SpacingValue.Text = $"{settings.Spacing:0}";
        OpacityValue.Text = $"{settings.BackgroundOpacity * 100:0}%";
        GapValue.Text = $"{settings.GapFromTray:0}";
        RightOffsetValue.Text = $"{settings.OffsetFromRight:0}";
        VerticalValue.Text = $"{settings.OffsetY:0}";

        PopulateMonitors(settings);
        RefreshColors();
        UpdateColorAvailability();

        _selectedBlock = selectedKind is null
            ? null
            : settings.Blocks.FirstOrDefault(b => b.Kind == selectedKind);

        RebuildBlocks();
        ShowDetails(_selectedBlock);

        _loading = false;
    }

    private void PopulateMonitors(AppSettings settings)
    {
        var screens = WinForms.Screen.AllScreens;
        var entries = screens
            .Select(screen => new MonitorEntry(screen.DeviceName,
                $"{screen.DeviceName}  —  {screen.Bounds.Width}×{screen.Bounds.Height}{(screen.Primary ? "  (primary)" : "")}"))
            .ToList();

        MonitorCombo.ItemsSource = entries;
        var primary = screens.FirstOrDefault(s => s.Primary)?.DeviceName;
        MonitorCombo.SelectedItem =
            entries.FirstOrDefault(e => string.Equals(e.Device, settings.MonitorDevice, StringComparison.OrdinalIgnoreCase))
            ?? entries.FirstOrDefault(e => e.Device == primary)
            ?? entries.FirstOrDefault();
        MonitorCombo.IsEnabled = !settings.ShowOnAllMonitors;
    }

    private void RebuildBlocks()
    {
        BlocksPanel.Children.Clear();

        foreach (var block in App.Settings.Blocks.OrderBy(b => b.Row).ThenBy(b => b.Order))
        {
            var grid = new Grid { Height = 36 };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(34) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(32) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(32) });

            var check = new CheckBox
            {
                IsChecked = block.Enabled,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(10, 0, 0, 0)
            };
            check.Checked += (_, _) => { block.Enabled = true; Apply(); };
            check.Unchecked += (_, _) => { block.Enabled = false; Apply(); };

            var name = new TextBlock
            {
                Text = block.Kind.Title(),
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(4, 0, 0, 0),
                FontSize = 12.5
            };

            var rowCombo = new ComboBox
            {
                ItemsSource = new[] { "Row 1", "Row 2" },
                SelectedIndex = block.Row - 1,
                Width = 82,
                VerticalAlignment = VerticalAlignment.Center
            };
            rowCombo.SelectionChanged += (_, _) =>
            {
                if (_loading) return;
                var newRow = rowCombo.SelectedIndex + 1;
                if (newRow == block.Row) return;
                block.Row = newRow;
                block.Order = App.Settings.Blocks.Count(b => b.Row == newRow);
                Apply();
                RebuildBlocks();
            };

            var up = SmallButton("↑", () => MoveBlock(block, -1));
            var down = SmallButton("↓", () => MoveBlock(block, 1));

            Grid.SetColumn(check, 0);
            Grid.SetColumn(name, 1);
            Grid.SetColumn(rowCombo, 2);
            Grid.SetColumn(up, 3);
            Grid.SetColumn(down, 4);
            grid.Children.Add(check);
            grid.Children.Add(name);
            grid.Children.Add(rowCombo);
            grid.Children.Add(up);
            grid.Children.Add(down);

            var selected = ReferenceEquals(block, _selectedBlock);
            var card = new Border
            {
                Child = grid,
                CornerRadius = new CornerRadius(6),
                BorderThickness = new Thickness(1),
                BorderBrush = new SolidColorBrush(Color.FromRgb(0xE4, 0xE4, 0xE4)),
                Background = new SolidColorBrush(selected ? Color.FromRgb(0xEA, 0xF3, 0xFB) : Colors.White),
                Margin = new Thickness(0, 0, 8, 4)
            };
            card.MouseLeftButtonUp += (_, _) =>
            {
                _selectedBlock = block;
                ShowDetails(block);
                RebuildBlocks();
            };

            BlocksPanel.Children.Add(card);
        }
    }

    private static Button SmallButton(string glyph, Action action)
    {
        var button = new Button
        {
            Content = glyph,
            Width = 28,
            Height = 24,
            MinWidth = 0,
            Padding = new Thickness(0),
            Margin = new Thickness(2),
            FontSize = 12
        };
        button.Click += (_, _) => action();
        return button;
    }

    private void MoveBlock(BlockSettings block, int delta)
    {
        var siblings = App.Settings.Blocks.Where(b => b.Row == block.Row).OrderBy(b => b.Order).ToList();
        var index = siblings.IndexOf(block);
        var target = index + delta;
        if (index < 0 || target < 0 || target >= siblings.Count) return;

        (siblings[index].Order, siblings[target].Order) = (siblings[target].Order, siblings[index].Order);
        Apply();
        RebuildBlocks();
    }

    private void ShowDetails(BlockSettings? block)
    {
        if (block is null)
        {
            DetailsEmpty.Visibility = Visibility.Visible;
            DetailsBody.Visibility = Visibility.Collapsed;
            return;
        }

        _loading = true;
        DetailsEmpty.Visibility = Visibility.Collapsed;
        DetailsBody.Visibility = Visibility.Visible;
        DetailsTitle.Text = block.Kind.Title();
        LabelBox.Text = block.Label ?? "";
        ChkIcon.IsChecked = block.ShowIcon;
        ChkLabel.IsChecked = block.ShowLabel;
        ChkPercent.IsChecked = block.ShowPercent;
        ChkPercent.Visibility = block.Kind.SupportsPercent() ? Visibility.Visible : Visibility.Collapsed;
        ChkTemp.IsChecked = block.ShowTemperature;
        ChkTemp.Visibility = block.Kind.SupportsTemperature() ? Visibility.Visible : Visibility.Collapsed;
        ChkPower.IsChecked = block.ShowPower;
        ChkPower.Visibility = block.Kind.SupportsPower() ? Visibility.Visible : Visibility.Collapsed;
        _loading = false;
    }

    private void ReadControls()
    {
        var settings = App.Settings;
        settings.Theme = ThemeCombo.SelectedItem as string ?? "Auto";
        settings.UseThemePalette = UsePaletteCheck.IsChecked == true;
        settings.FontFamily = FontCombo.SelectedItem as string ?? "Segoe UI";
        settings.FontSize = Math.Round(SizeSlider.Value);
        settings.Spacing = Math.Round(SpacingSlider.Value);
        settings.BackgroundOpacity = Math.Round(OpacitySlider.Value, 2);
        settings.NetUnit = NetUnitCombo.SelectedItem as string ?? "Mbps";
        settings.ShowOnAllMonitors = AllMonitorsCheck.IsChecked == true;
        if (MonitorCombo.SelectedItem is MonitorEntry entry) settings.MonitorDevice = entry.Device;
        settings.GapFromTray = Math.Round(GapSlider.Value);
        settings.OffsetFromRight = Math.Round(RightOffsetSlider.Value);
        settings.OffsetY = Math.Round(VerticalSlider.Value);
        settings.StartWithWindows = StartWithWindowsCheck.IsChecked == true;
        settings.StartElevated = StartElevatedCheck.IsChecked == true;
    }

    private void Apply(bool rebuildOverlays = false)
    {
        if (_loading) return;

        ReadControls();
        App.ApplySettings();
        if (rebuildOverlays) App.RebuildOverlays();

        RefreshColors();
        UpdateColorAvailability();
    }

    public void UpdatePreview(bool rebuild)
    {
        if (rebuild) _preview.Apply(App.Settings, App.CurrentPalette);
        else _preview.ApplyStyle(App.Settings, App.CurrentPalette);

        _preview.UpdateValues(App.Latest);
    }

    private void StartupChanged()
    {
        if (_loading) return;

        App.Settings.StartWithWindows = StartWithWindowsCheck.IsChecked == true;
        App.Settings.StartElevated = StartElevatedCheck.IsChecked == true;

        if (App.Settings.StartWithWindows && App.Settings.StartElevated && !App.IsElevated)
        {
            var answer = MessageBox.Show(this,
                "Elevated startup has to be registered by an administrator once.\n\nRestart Taskbar Monitor as administrator now?",
                "Taskbar Monitor", MessageBoxButton.YesNo, MessageBoxImage.Question);

            if (answer == MessageBoxResult.Yes)
            {
                App.RestartElevated();
                return;
            }

            _loading = true;
            StartElevatedCheck.IsChecked = false;
            _loading = false;
            App.Settings.StartElevated = false;
        }

        Startup.Apply(App.Settings.StartWithWindows, App.Settings.StartElevated);
        UpdateStatus();
        App.QueueSave();
    }

    private void UpdateStatus()
    {
        ElevationBadge.Text = App.IsElevated ? "Administrator" : "Standard user";

        CpuStatusText.Text = App.Metrics.CpuTemps.InitializationFinished
            ? "CPU temperature — " + App.Metrics.CpuTemps.Status
            : "CPU temperature — reading sensors…";

        GpuStatusText.Text = App.Metrics.Gpu.Available
            ? "GPU sensors — NVML ready."
            : "GPU sensors — no NVIDIA GPU detected; GPU values show as --.";

        StartupStatusText.Text = App.Settings.StartWithWindows
            ? App.Settings.StartElevated
                ? "Startup — scheduled task with highest privileges (no UAC prompt at logon)."
                : "Startup — current-user Run key."
            : "Startup — disabled.";
    }

    private void RestartAdmin_Click(object sender, RoutedEventArgs e)
    {
        var answer = MessageBox.Show(this,
            "Restart Taskbar Monitor as administrator? The current window will close.",
            "Taskbar Monitor", MessageBoxButton.YesNo, MessageBoxImage.Question);

        if (answer == MessageBoxResult.Yes) App.RestartElevated();
    }

    private void OpenFolder_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            Directory.CreateDirectory(SettingsStore.Folder);
            Process.Start(new ProcessStartInfo(SettingsStore.Folder) { UseShellExecute = true });
        }
        catch (Exception ex)
        {
            Log.Error("open settings folder", ex);
        }
    }

    private void ResetDefaults_Click(object sender, RoutedEventArgs e)
    {
        var answer = MessageBox.Show(this, "Reset every setting to its default?",
            "Taskbar Monitor", MessageBoxButton.YesNo, MessageBoxImage.Question);
        if (answer != MessageBoxResult.Yes) return;

        App.ResetSettings();
        _selectedBlock = null;
        LoadFromSettings();
        UpdatePreview(true);
        UpdateStatus();
    }

    private void Close_Click(object sender, RoutedEventArgs e) => Close();
}

