    var toggle = new CheckBox { Style = (Style)FindResource("Switch"), IsChecked = block.Enabled, VerticalAlignment = Center, ToolTip = "Show on the taskbar" };
    toggle.Checked += (_, _) => { block.Enabled = true; Apply(); RebuildBlocks(); };
