    var chevron = new Path { Data = Geometry.Parse(expanded ? "M2,7 L6,3 L10,7" : "M2,4 L6,8 L10,4"), Stroke = mutedBrush, StrokeThickness = 1.5, Width = 12, Height = 12, Stretch = Stretch.Uniform, VerticalAlignment = Center, Margin = new Thickness(12,0,2,0) };

    Grid.SetColumn(icon, 0); ... text 1, toggle 2, chevron 3.
    header.Children.Add...

    header.MouseLeftButtonUp += (_, _) =>
    {
        _selectedBlock = expanded ? null : block;
        RebuildBlocks();
    };

    content.Children.Add(header);

    if (expanded)
    {
        content.Children.Add(new Border { Height = 1, Background = LineSoft, Margin = new Thickness(16,0,16,0) });
        content.Children.Add(BuildOptions(block));
