private FrameworkElement BuildOptions(BlockSettings block)
{
    var panel = new StackPanel { Margin = new Thickness(16, 12, 16, 14) };

    // label
    var labelGrid = new Grid { Margin = new Thickness(0, 0, 0, 8) };
    labelGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(90) });
    labelGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
    var labelTitle = new TextBlock { Text = "Label", VerticalAlignment = VerticalAlignment.Center };
    var labelBox = new TextBox { Text = block.Label ?? "", MaxWidth = 280, HorizontalAlignment = HorizontalAlignment.Left };
    labelBox.TextChanged += (_, _) =>
    {
        if (_loading) return;
        block.Label = string.IsNullOrWhiteSpace(labelBox.Text) ? null : labelBox.Text.Trim();
        Apply();
    };
    Grid.SetColumn(labelBox, 1);
    labelGrid.Children.Add(labelTitle);
    labelGrid.Children.Add(labelBox);
    panel.Children.Add(labelGrid);

    // toggles
    var wrap = new WrapPanel();
    wrap.Children.Add(ToggleCell("Icon", block.ShowIcon, v => { block.ShowIcon = v; Apply(); }));
    wrap.Children.Add(ToggleCell("Name", block.ShowLabel, v => { block.ShowLabel = v; Apply(); }));
    if (block.Kind.SupportsPercent())
        wrap.Children.Add(ToggleCell("Percentage", block.ShowPercent, v => { block.ShowPercent = v; Apply(); }));
    if (block.Kind.SupportsTemperature())
        wrap.Children.Add(ToggleCell("Temperature", block.ShowTemperature, v => { block.ShowTemperature = v; Apply(); }));
    if (block.Kind.SupportsPower())
        wrap.Children.Add(ToggleCell("Power (W)", block.ShowPower, v => { block.ShowPower = v; Apply(); }));
    panel.Children.Add(wrap);

    // line + order
    var footer = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 10, 0, 0) };
    footer.Children.Add(new TextBlock { Text = "Line", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0,0,10,0), Foreground = muted });
    footer.Children.Add(SegmentButton("Top", block.Row == 1, () => SetBlockRow(block, 1)));
    footer.Children.Add(SegmentButton("Bottom", block.Row == 2, () => SetBlockRow(block, 2)));
    footer.Children.Add(new Border { Width = 18 });
    footer.Children.Add(ChipButton("↑", "Move up", () => MoveBlock(block, -1)));
    footer.Children.Add(ChipButton("↓", "Move down", () => MoveBlock(block, 1)));
    panel.Children.Add(footer);

    return panel;
}
